"""追加RAND3枝のうち、既存台詞だけで場面を復旧できるものを入れ替える。

新しい台詞は作らず、各ファイルの場面ラベルと現在の追加台詞群を照合して、
恋慕・通常それぞれの A == 1 枝だけを正しい COM へ戻す。
"""

from __future__ import annotations

from pathlib import Path
import re


ROOT = Path(__file__).resolve().parents[1]
CHAR_DIR = ROOT / "ERB" / "CHAR"


# target COM -> current COM whose four added lines belong to that target scene.
# The mappings were determined from the scene labels and the existing text; no
# dialogue is generated by this repair.
REPAIRS: dict[str, dict[tuple[int, int], dict[int, int]]] = {
    "CHAR_35_*_COM.ERB": {
        (280, 284): {280: 281, 281: 284, 282: 282, 283: 280, 284: 283},
        (410, 414): {410: 410, 411: 412, 412: 411, 413: 414, 414: 413},
    },
    "CHAR_36_*_COM.ERB": {
        (280, 284): {280: 283, 281: 280, 282: 284, 283: 282, 284: 281},
        (410, 414): {410: 414, 411: 410, 412: 411, 413: 412, 414: 413},
    },
    "CHAR_38_*_COM.ERB": {
        (280, 284): {280: 280, 281: 283, 282: 284, 283: 282, 284: 281},
        (410, 414): {410: 413, 411: 410, 412: 412, 413: 411, 414: 414},
    },
    "CHAR_41_*_COM.ERB": {
        (280, 284): {280: 280, 281: 284, 282: 283, 283: 281, 284: 282},
        (410, 414): {410: 410, 411: 411, 412: 412, 413: 413, 414: 414},
    },
    "CHAR_49_*_COM.ERB": {
        (280, 284): {280: 282, 281: 283, 282: 284, 283: 280, 284: 281},
        (410, 414): {410: 411, 411: 413, 412: 410, 413: 414, 414: 412},
    },
}


def leading_indent(line: str) -> str:
    return line[: len(line) - len(line.lstrip())]


def command_ranges(lines: list[str], start: int, end: int) -> dict[int, tuple[int, int]]:
    starts: list[tuple[int, int]] = []
    for i in range(start, end):
        match = re.match(r"^\s*(?:IF|ELSEIF) SELECTCOM == (\d+)", lines[i])
        if match:
            starts.append((i, int(match.group(1))))
    if not starts:
        raise RuntimeError(f"SELECTCOM chain not found in {start + 1}:{end}")
    result: dict[int, tuple[int, int]] = {}
    for pos, (line_no, command) in enumerate(starts):
        branch_end = starts[pos + 1][0] if pos + 1 < len(starts) else end
        if command in result:
            raise RuntimeError(f"duplicate COM{command}")
        result[command] = (line_no, branch_end)
    return result


def a1_print_indices(lines: list[str], start: int, end: int) -> tuple[list[int], list[int]]:
    a0_markers = [i for i in range(start, end) if lines[i].strip() == "IF A == 0"]
    if len(a0_markers) != 2:
        raise RuntimeError(f"expected two A == 0 branches, got {len(a0_markers)} at {start + 1}")

    result: list[list[int]] = []
    for a0_marker in a0_markers:
        branch_indent = len(lines[a0_marker]) - len(lines[a0_marker].lstrip())
        a1_marker = next(
            (
                i
                for i in range(a0_marker + 1, end)
                if len(lines[i]) - len(lines[i].lstrip()) == branch_indent
                and lines[i].strip() == "ELSEIF A == 1"
            ),
            None,
        )
        if a1_marker is None:
            raise RuntimeError(f"A == 1 branch not found after {a0_marker + 1}")
        a2_marker = next(
            (
                i
                for i in range(a1_marker + 1, end)
                if len(lines[i]) - len(lines[i].lstrip()) == branch_indent
                and lines[i].strip() == "ELSE"
            ),
            None,
        )
        if a2_marker is None:
            raise RuntimeError(f"A == 2 branch not found after {a1_marker + 1}")
        end_marker = next(
            (
                i
                for i in range(a2_marker + 1, end)
                if len(lines[i]) - len(lines[i].lstrip()) == branch_indent
                and lines[i].strip() == "ENDIF"
            ),
            None,
        )
        if end_marker is None:
            raise RuntimeError(f"A branch terminator not found after {a2_marker + 1}")

        a1_indices = [
            i for i in range(a1_marker + 1, a2_marker) if "PRINT" in lines[i] and "「" in lines[i]
        ]
        a2_indices = [
            i for i in range(a2_marker + 1, end_marker) if "PRINT" in lines[i] and "「" in lines[i]
        ]
        if len(a1_indices) != 1 or len(a2_indices) != 1:
            raise RuntimeError(
                f"expected one added PRINT line per branch at {a0_marker + 1}, "
                f"got A1={len(a1_indices)}, A2={len(a2_indices)}"
            )
        result.append(a1_indices + a2_indices)
    return result[0], result[1]


def copy_slot(lines: list[str], target_indices: list[int], source_lines: list[str]) -> int:
    if len(target_indices) != len(source_lines):
        raise RuntimeError("source/target A == 1 branch length mismatch")
    changed = 0
    for target_index, source_line in zip(target_indices, source_lines):
        replacement = leading_indent(lines[target_index]) + source_line.lstrip()
        if lines[target_index] != replacement:
            lines[target_index] = replacement
            changed += 1
    return changed


def repair_file(path: Path, mappings: dict[tuple[int, int], dict[int, int]]) -> int:
    text = path.read_bytes().decode("cp932").replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    total_changed = 0

    for (first, last), mapping in mappings.items():
        marker = f";--- COM{first}-{last}"
        group_start = next(i for i, line in enumerate(lines) if marker in line)
        if first == 280:
            next_marker = ";--- COM410-414"
        else:
            next_marker = ";--- COM0 "
        group_end = next(i for i in range(group_start + 1, len(lines)) if next_marker in lines[i])
        ranges = command_ranges(lines, group_start, group_end)

        required = set(range(first, last + 1))
        if set(ranges) != required:
            raise RuntimeError(
                f"{path.name}: COM{first}-{last} contains {sorted(ranges)}, expected {sorted(required)}"
            )

        slots: dict[int, tuple[list[int], list[int]]] = {}
        for command in required:
            start, end = ranges[command]
            slots[command] = a1_print_indices(lines, start, end)

        # Snapshot all source branches before modifying any target branch.
        source_lines = {
            command: (
                [lines[i] for i in slots[command][0]],
                [lines[i] for i in slots[command][1]],
            )
            for command in required
        }

        for target, source in mapping.items():
            total_changed += copy_slot(lines, slots[target][0], source_lines[source][0])
            total_changed += copy_slot(lines, slots[target][1], source_lines[source][1])

    if total_changed:
        encoded = ("\r\n".join(lines)).encode("cp932")
        path.write_bytes(encoded)
    return total_changed


def main() -> None:
    for pattern, mappings in REPAIRS.items():
        matches = list(CHAR_DIR.glob(pattern))
        if len(matches) != 1:
            raise RuntimeError(f"{pattern}: expected one file, got {len(matches)}")
        path = matches[0]
        changed = repair_file(path, mappings)
        print(f"{path.name}: {changed} lines repaired")


if __name__ == "__main__":
    main()
